import {reactFetchJSON} from '@github-ui/verified-fetch'
import {useCallback, useState} from 'react'
import {useClickAnalytics} from '@github-ui/use-analytics'

export const useDismissUpsell = (dismissURL: string) => {
  const [isDismissed, setDismissed] = useState(false)
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const handleDismiss = useCallback(() => {
    setDismissed(true)
    sendClickAnalyticsEvent({
      category: 'copilot_assisted_review_upsell',
      action: 'dismiss_upsell_click',
    })
    try {
      reactFetchJSON(dismissURL, {
        method: 'POST',
      })
    } catch {
      // fail silently, nothing the user can do to fix it
    }
  }, [dismissURL, sendClickAnalyticsEvent])

  return {isDismissed, handleDismiss}
}
