import {Link, Button} from '@primer/react'
import {useDismissUpsell} from './hooks'
import {CopilotIcon} from '@primer/octicons-react'
import {useClickAnalytics, useAnalytics} from '@github-ui/use-analytics'
import {useEffect, useRef, useState} from 'react'

export interface CopilotAssistedReviewUpsellProps {
  dismissURL: string
  upsellURL: string
}

export function CopilotAssistedReviewUpsell({dismissURL, upsellURL}: CopilotAssistedReviewUpsellProps) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const {sendAnalyticsEvent} = useAnalytics()
  const {isDismissed, handleDismiss} = useDismissUpsell(dismissURL)
  const [shownEventSent, setShownEventSent] = useState(false)
  const elementRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!elementRef.current) return

    const details = elementRef.current.closest('details')
    if (!details) return

    if (details.open && !isDismissed && !shownEventSent) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setShownEventSent(true)
      sendAnalyticsEvent('copilot_assisted_review_upsell.shown')
      return
    }

    function handleToggle() {
      if (details?.open && !isDismissed && !shownEventSent) {
        setShownEventSent(true)
        sendAnalyticsEvent('copilot_assisted_review_upsell.shown')
      }
    }
    details.addEventListener('toggle', handleToggle, {once: true})
    return () => {
      details.removeEventListener('toggle', handleToggle)
    }
  }, [elementRef, isDismissed, shownEventSent, sendAnalyticsEvent])

  if (isDismissed) return null
  return (
    <>
      <div ref={elementRef} className="select-menu-divider">
        Available on Copilot Pro
        <Button variant="link" className="float-right" onClick={handleDismiss}>
          Dismiss
        </Button>
      </div>
      <div className="select-menu-item text-normal">
        <Link
          target="_blank"
          rel="noopener noreferrer"
          href={upsellURL}
          onClick={() => {
            sendClickAnalyticsEvent({
              category: 'copilot_assisted_review_upsell',
              action: 'upsell_click',
            })
          }}
        >
          <div className="select-menu-item-gravatar">
            <span className="js-copilot-avatar d-flex flex-justify-center flex-sm-items-center">
              <CopilotIcon size={16} />
            </span>
          </div>
          <div className="select-menu-item-text lh-condensed">
            <span className="select-menu-item-heading">
              <span className="js-username">Copilot</span>
              <span className="description js-description" />
              <span className="description d-block ml-4 pl-1 pr-2 js-extended-description">
                Try Copilot code review for 30 days free.
              </span>
            </span>
          </div>
        </Link>
      </div>
    </>
  )
}

try{ CopilotAssistedReviewUpsell.displayName ||= 'CopilotAssistedReviewUpsell' } catch {}